contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: first deposit some Ether (may be zero), then attempt withdraw
    function run(uint256 deposit) public payable {
        require(address(this).balance >= deposit, "insufficient balance to send");

        // record before-values
        uint256 beforeUser = c.getBalance(address(this));
        uint256 beforeVault = address(c).balance;

        // perform a deposit (may revert)
        bool depReverted = false;
        try c.addToBalance{value: deposit}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // read intermediate values
        uint256 midUser = c.getBalance(address(this));
        uint256 midVault = address(c).balance;

        // attempt withdrawal and observe whether it reverts
        bool withReverted = false;
        try c.withdrawBalance() {
            withReverted = false;
        } catch {
            withReverted = true;
        }

        // read after-values
        uint256 afterUser = c.getBalance(address(this));
        uint256 afterVault = address(c).balance;

        // If withdraw succeeded, then the stored user balance must be zero and the contract's balance must have decreased by at least the amount that was recorded for this user before the withdraw was executed (i.e., midUser).
        // Note: we allow deposit to have reverted; rule only constrains successful withdraws.
        assert(withReverted || (afterUser == 0 && beforeVault >= afterVault && beforeVault - afterVault >= midUser));
    }

    // allow this test contract to receive Ether
    receive() external payable {}
}

contract InvMutTest {
