contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: send 'amount' wei to c via addToBalance and check invariants
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund addToBalance");
        // read before-values
        uint beforeRecorded = c.getBalance(address(this));
        uint beforeContractBal = address(c).balance;

        // perform the state-changing call: addToBalance with provided amount
        c.addToBalance{value: amount}();

        // read after-values
        uint afterRecorded = c.getBalance(address(this));
        uint afterContractBal = address(c).balance;

        // General invariant: if the call succeeded (we reached here), then
        // recorded balance increased by exactly 'amount' and contract balance increased by exactly 'amount'
        assert(afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount);
    }

    // Allow receiving Ether so the test contract can be funded
    receive() external payable {}
}
